```file:site/styles.css
body {
 font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
 background: #0f1117;
 color: #e4e6eb;
 margin: 0;
 padding: 2rem;
 line-height: 1.6;
}
.panel {
 background: #1a1d24;
 border: 1px solid #2a2e36;
 border-radius: 8px;
 padding: 1.25rem;
 margin-bottom: 1.25rem;
}
.promise p {
 font-size: 1.1rem;
 color: #c9d1d9;
}
.mission h3 {
 margin-top: 0;
 color: #79c0ff;
}
.stats {
 display: grid;
 grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
 gap: 0.75rem;
 margin-top: 1.5rem;
}
.stat {
 background: #1a1d24;
 border: 1px solid #2a2e36;
 border-radius: 6px;
 padding: 0.75rem;
}
.stat span {
 display: block;
 font-size: 0.8rem;
 text-transform: uppercase;
 letter-spacing: 0.05em;
 color: #8b949e;
}
.stat strong {
 font-size: 1.2rem;
 color: #f0f6fc;
}
.accent {
 color: #79c0ff;
}
.progress-bar {
 height: 8px;
 background: #2a2e36;
 border-radius: 4px;
 margin-bottom: 4px;
}
.progress-bar-filled {
 background: #79c0ff;
 width: 0%;
 transition: width 0.3s;
}
.nav {
 background: #1a1d24;
 padding: 1rem;
 border-bottom: 1px solid #2a2e36;
}
.nav nav a {
 color: #e4e6eb;
 text-decoration: none;
 margin-right: 1rem;
}
.nav nav a:hover {
 text-decoration: underline;
}
.footer {
 background: #1a1d24;
 padding: 1rem;
 border-top: 1px solid #2a2e36;
 margin-top: 2rem;
}
.footer nav a {
 color: #e4e6eb;
 text-decoration: none;
 margin-right: 1rem;
}
.footer p {
 color: #8b949e;
 text-align: center;
}
